# Put a person on hold, or take them off it. Validate the body before touching the store, so a refusal writes nothing.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: hold
hold:
  class: net.officefloor.hq.app.person.ValidateHold
  next: load
load:
  class: net.officefloor.hq.app.person.LoadPerson
  govern: [ transaction ]
  next: rollup-before
rollup-before:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.person.HoldPerson
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.person.RecordPersonHold
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPerson
  govern: [ transaction ]
# The people on the sheet, in the order they were added.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: respond
respond:
  class: net.officefloor.hq.app.person.RespondWithPeople
  govern: [ readonly-transaction ]
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Whether to hold or release the person. Publishes it, with the user making the change. */
public class ValidateHold {
    public void validate(@RequestBody HoldRequest request, Out<HoldInput> hold, Out<ChangedBy> changedBy)
            throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        if (request == null || request.held() == null) {
            throw new BadRequestException("Say whether to hold or release the person");
        }
        hold.set(new HoldInput(request.held()));
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.person;

/** A validated hold change: whether the person is to be held. */
public record HoldInput(boolean held) {
}
package net.officefloor.hq.app.person;

/** Whether to put the person on hold (true) or take them off it (false), and the signed-in user (`by`) doing it. */
public record HoldRequest(Boolean held, String by) {
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class LoadPerson {
    public void load(@Val SheetResponse sheet, @PathVariable("personId") String personId,
            PersonRepository repository, Out<Person> person) throws BadRequestException {
        Person found = null;
        try {
            found = repository.find(sheet.id(), Long.parseLong(personId));
        } catch (NumberFormatException e) {
            // not an id: no such person
        }
        if (found == null) {
            throw new BadRequestException("No such person on this sheet");
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.plugin.variable.Val;

/** Puts the person on hold or takes them off it; refuses when they are in that state already. */
public class HoldPerson {
    public void hold(@Val HoldInput input, @Val Person person, PersonRepository repository)
            throws BadRequestException {
        if (person.isHeld() == input.held() || !repository.hold(person.getId(), input.held())) {
            throw new BadRequestException(input.held() ? "That person is already on hold; reload the sheet"
                    : "That person is not on hold; reload the sheet");
        }
        person.setHeld(input.held());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordPersonHold {
    public void record(@Val Person person, @Val ChangedBy by, Audit audit) {
        audit.record((person.isHeld() ? "PERSON_HELD" : "PERSON_RELEASED") + " sheet=" + person.getSheetId() + " by="
                + by.name() + " name=" + person.getName());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPerson {
    public void respond(@Val Person person, ObjectResponse<PersonResponse> response) {
        response.send(PersonResponse.from(person));
    }
}
package net.officefloor.hq.app.person;

import java.util.List;
import net.officefloor.hq.app.sheet.SheetResponse;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;

public class RespondWithPeople {
    public void respond(@Val SheetResponse sheet, PersonRepository repository,
            ObjectResponse<List<PersonResponse>> response) {
        response.send(repository.list(sheet.id()).stream().map(PersonResponse::from).toList());
    }
}
package net.officefloor.hq.app.person;

/** A person, with their statement count and their last statement's due-total ("n/a" when it had none) and date
 *  (both null before their first statement), the date they are retired from (null: not retired), and whether they are on hold. */
public record PersonResponse(long id, String name, String grade, long version, int statementCount, String statedTotal,
        String statementDate, String retiredFrom, boolean held) {
    public static PersonResponse from(Person person) {
        Statements s = person.getStatements();
        return new PersonResponse(person.getId(), person.getName(), person.getGrade(), person.getVersion(), s.count(),
                s.count() == 0 ? null : s.lastDueTotal() == null ? "n/a" : s.lastDueTotal().toPlainString(),
                s.lastDate() == null ? null : s.lastDate().toString(),
                person.getRetiredFrom() == null ? null : person.getRetiredFrom().toString(), person.isHeld());
    }
}
package net.officefloor.hq.app.person;

import java.sql.PreparedStatement;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The people on each sheet; ids are assigned in the order people are added. */
@Repository
public class PersonRepository {

    /** A person's columns, with their statement count and their last statement's due-total and date. */
    private static final String COLUMNS = "p.id, p.sheet_id, p.name, p.grade, p.version, p.retired_from, p.held,"
            + " (SELECT COUNT(*) FROM statement s WHERE s.person_id = p.id) AS statement_count,"
            + " (SELECT s.due_total FROM statement s WHERE s.person_id = p.id ORDER BY s.id DESC LIMIT 1) AS stated_total,"
            + " (SELECT s.taken_on FROM statement s WHERE s.person_id = p.id ORDER BY s.id DESC LIMIT 1) AS statement_date";

    private static final RowMapper<Person> ROW = (rs, n) -> {
        Person person = new Person(rs.getLong("id"), rs.getString("sheet_id"), rs.getString("name"),
                rs.getString("grade"), rs.getLong("version"));
        person.setStatements(new Statements(rs.getInt("statement_count"), rs.getBigDecimal("stated_total"),
                rs.getObject("statement_date", LocalDate.class)));
        person.setRetiredFrom(rs.getObject("retired_from", LocalDate.class));
        person.setHeld(rs.getBoolean("held"));
        return person;
    };

    static final String CHANGED = "Someone else has saved this person since you opened it; the form now shows their changes";

    static final String NAME_TAKEN = "That name is already in use on this sheet";

    private final JdbcTemplate jdbc;

    public PersonRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's people, in the order they were added. */
    public List<Person> list(String sheetId) {
        return jdbc.query("SELECT " + COLUMNS + " FROM person p WHERE p.sheet_id = ? ORDER BY p.id", ROW, sheetId);
    }

    public Person find(String sheetId, long id) {
        return jdbc.query("SELECT " + COLUMNS + " FROM person p WHERE p.sheet_id = ? AND p.id = ?", ROW, sheetId, id)
                .stream().findFirst().orElse(null);
    }

    /** The person on the sheet with this name, ignoring case and surrounding spaces; null when none. */
    public Person findByName(String sheetId, String name) {
        return jdbc.query("SELECT " + COLUMNS + " FROM person p WHERE p.sheet_id = ? AND p.name_key = LOWER(TRIM(?))",
                ROW, sheetId, name).stream().findFirst().orElse(null);
    }

    /** Whether another person on the sheet has this name, ignoring case and surrounding spaces. */
    public boolean nameTaken(String sheetId, String name, Long exceptId) {
        Integer n = jdbc.queryForObject(
                "SELECT COUNT(*) FROM person WHERE sheet_id = ? AND name_key = LOWER(TRIM(?)) AND id <> ?",
                Integer.class, sheetId, name, exceptId == null ? -1L : exceptId);
        return n != null && n > 0;
    }

    public Person insert(String sheetId, String name, String grade) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO person (sheet_id, name, grade) VALUES (?, ?, ?)", new String[] { "id" });
            ps.setString(1, sheetId);
            ps.setString(2, name);
            ps.setString(3, grade);
            return ps;
        }, keys);
        return new Person(keys.getKey().longValue(), sheetId, name, grade, 0);
    }

    /** Saves the person if it is still at the version it was loaded at, moving it to the next
     *  version; false (nothing written) when someone else saved it in the meantime. */
    public boolean update(Person person) {
        int n = jdbc.update("UPDATE person SET name = ?, grade = ?, version = version + 1 WHERE id = ? AND version = ?",
                person.getName(), person.getGrade(), person.getId(), person.getVersion());
        if (n == 0) {
            return false;
        }
        person.setVersion(person.getVersion() + 1);
        return true;
    }

    /** Retire the person from the date; false (nothing written) when they were retired already. */
    public boolean retire(long id, LocalDate from) {
        return jdbc.update("UPDATE person SET retired_from = ? WHERE id = ? AND retired_from IS NULL",
